import{_ as p,a0 as l,w as o,s as d,ao as h,I as t,x as a,a1 as e,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"在 Linux 上调整命令历史 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上调整命令历史 | LCTT (202009) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上调整命令历史 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上调整命令历史 | LCTT (202009) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202009/20200415 Tweaking history on Linux","title":"在 Linux 上调整命令历史","tag":"202009","desc":""},"relativePath":"202009/20200415 Tweaking history on Linux.md","filePath":"[post].md"}'),r={name:"202009/20200415 Tweaking history on Linux.md"};function c(g,s,k,b,u,y){const i=l("Link");return o(),d("div",null,[s[15]||(s[15]=h(`<h1 id="在-linux-上调整命令历史" tabindex="-1">在 Linux 上调整命令历史 <a class="header-anchor" href="#在-linux-上调整命令历史" aria-label="Permalink to “在 Linux 上调整命令历史”">​</a></h1><blockquote><p>在 Linux 系统上，bash shell 的 history 命令可以方便地回顾和重用命令，但是你要控制它记住多少，忘记多少，有很多事情要做。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202009/08/232418c2121m2euw3aaw58.jpg" alt=""></p><p>Linux 系统中的 bash <code>history</code> 命令有助于记住你以前运行过的命令，并重复这些命令，而不必重新输入。</p><p>如果可以的话，你肯定会很高兴不用翻阅十几页的手册，每过一会再次列出你的文件，而是通过输入 <code>history</code> 查看以前运行的命令。在这篇文章中，我们将探讨如何让 <code>history</code> 命令记住你希望它记住的内容，并忘记那些可能没有什么“历史价值”的命令。</p><h3 id="查看你的命令历史" tabindex="-1">查看你的命令历史 <a class="header-anchor" href="#查看你的命令历史" aria-label="Permalink to “查看你的命令历史”">​</a></h3><p>要查看以前运行过的命令，你只需输入 <code>history</code>。你可能会看到一长串命令。记忆的命令数量取决于在 <code>~/.bashrc</code> 文件中设置的名为 <code>$HISTSIZE</code> 的环境变量，但是如果你想保存更多或更少的命令，你可以根据你的需要改变这个设置。</p><p>要查看历史记录，请使用 <code>history</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ history</span></span>
<span class="line"><span>209 uname -v</span></span>
<span class="line"><span>210 date</span></span>
<span class="line"><span>211 man chage</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>要查看将显示的最大命令数量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $HISTSIZE</span></span>
<span class="line"><span>500</span></span></code></pre></div><p>你可以通过运行这样的命令来改变 <code>$HISTSIZE</code> 并使之永久化：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ export HISTSIZE=1000</span></span>
<span class="line"><span>$ echo &quot;HISTSIZE=1000&quot; &gt;&gt; ~/.bashrc</span></span></code></pre></div><p>在为你保留多少历史记录和当你输入 <code>history</code> 时显示多少历史记录之间也有区别。<code>$HISTSIZE</code> 变量控制显示多少历史记录，而 <code>$HISTFILESIZE</code> 变量控制在你的 <code>.bash_history</code> 文件中保留多少命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $HISTSIZE</span></span>
<span class="line"><span>1000</span></span>
<span class="line"><span>$ echo $HISTFILESIZE</span></span>
<span class="line"><span>2000</span></span></code></pre></div><p>你可以通过计算历史文件中的行数来验证第二个变量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wc -l .bash_history</span></span>
<span class="line"><span>2000 .bash_history</span></span></code></pre></div><p>需要注意的是，在登录会话中输入的命令在注销前不会被添加到你的 <code>.bash_history</code> 文件中，尽管它们会立即显示在 <code>history</code> 命令输出中。</p><h3 id="使用历史" tabindex="-1">使用历史 <a class="header-anchor" href="#使用历史" aria-label="Permalink to “使用历史”">​</a></h3><p>有三种方法可以重发你在 <code>history</code> 中发现的命令。最简单的方法，特别是当你想重用的命令是最近运行的时候，通常是输入一个 <code>!</code> 后面跟上命令中足够多的首字母来唯一地识别它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ !u</span></span>
<span class="line"><span>uname -v</span></span>
<span class="line"><span>#37-Ubuntu SMP Thu Mar 26 20:41:27 UTC 2020</span></span></code></pre></div><p>另一种简单的重复命令的方法是，只需按上箭头键，直到显示了该命令，然后按回车键。</p><p>另外，如果你运行 <code>history</code> 命令，并看到你想重新运行的命令被列出，你可以输入一个 <code>!</code> 后面跟着命令左边显示的序号。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ !209</span></span>
<span class="line"><span>uname -v</span></span>
<span class="line"><span>#37-Ubuntu SMP Thu Mar 26 20:41:27 UTC 2020</span></span></code></pre></div><h3 id="隐藏历史" tabindex="-1">隐藏历史 <a class="header-anchor" href="#隐藏历史" aria-label="Permalink to “隐藏历史”">​</a></h3><p>如果你想在一段时间内停止记录命令，你可以使用这个命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ set +o history</span></span></code></pre></div><p>当你输入 <code>history</code> 时，你输入的命令不会显示出来，当你退出会话或退出终端时，它们也不会被添加到你的 <code>.bash_history</code> 文件中。</p><p>要取消这个设置，使用 <code>set -o history</code>。</p><p>要使它永久化，你可以把它添加到你的 <code>.bashrc</code> 文件中，尽管不使用命令历史记录通常不是一个好主意。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;set +o history&#39; &gt;&gt; ~/.bashrc</span></span></code></pre></div><p>要暂时清除历史记录，这样在输入 <code>history</code> 时只显示之后输入的命令，可以使用 <code>history -c</code>（清除）命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ history | tail -3</span></span>
<span class="line"><span>209 uname -v</span></span>
<span class="line"><span>210 date</span></span>
<span class="line"><span>211 man chage</span></span>
<span class="line"><span>$ history -c</span></span>
<span class="line"><span>$ history</span></span>
<span class="line"><span>1  history</span></span></code></pre></div><p>注意：在输入 <code>history -c</code> 后输入的命令不会被添加到 <code>.bash_history</code> 文件中。</p><h3 id="控制历史" tabindex="-1">控制历史 <a class="header-anchor" href="#控制历史" aria-label="Permalink to “控制历史”">​</a></h3><p>许多系统上的 <code>history</code> 命令的设置会默认包括一个名为 <code>$HISTCONTROL</code> 的变量，以确保即使你连续运行同一命令七次，也只会被记住一次。它还可以确保你在首先输入一个或多个空格后跟着的命令将从你的命令历史记录中忽略。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep HISTCONTROL .bashrc</span></span>
<span class="line"><span>HISTCONTROL=ignoreboth</span></span></code></pre></div><p><code>ignoreboth</code> 的意思是“忽略重复的命令和以空格开头的命令”。例如，如果你输入这些命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo try this</span></span>
<span class="line"><span>$ date</span></span>
<span class="line"><span>$ date</span></span>
<span class="line"><span>$ date</span></span>
<span class="line"><span>$   pwd</span></span>
<span class="line"><span>$ history</span></span></code></pre></div><p>你的 <code>history</code> 命令应该像这样报告：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ history</span></span>
<span class="line"><span>$ echo try this</span></span>
<span class="line"><span>$ date</span></span>
<span class="line"><span>$ history</span></span></code></pre></div><p>请注意，连续的 <code>date</code> 命令被缩减为一条，以空格缩进的命令被省略。</p><h3 id="忽略历史" tabindex="-1">忽略历史 <a class="header-anchor" href="#忽略历史" aria-label="Permalink to “忽略历史”">​</a></h3><p>要忽略某些命令，使它们在你输入 <code>history</code> 时不会出现，也不会被添加到你的 <code>.bash_history</code> 文件中，可以使用 <code>$HISTIGNORE</code> 设置。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ export HISTIGNORE=”history:cd:exit:ls:pwd:man”</span></span></code></pre></div><p>这个设置将导致所有的 <code>history</code>、<code>cd</code>、<code>exit</code>、<code>ls</code>、<code>pwd</code> 和 <code>man</code> 命令从你的 <code>history</code> 命令的输出和 <code>.bash_history</code> 文件中被忽略。</p><p>如果你想把这个设置变成永久性的，你必须把它添加到你的 <code>.bashrc</code> 文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;HISTIGNORE=&quot;history:cd:exit:ls:pwd:man&quot;&#39; &gt;&gt; .bashrc</span></span></code></pre></div><p>这个设置只是意味着当你回看以前运行的命令时，列表不会被你在查看命令历史记录时不想看到的命令所干扰。</p><h3 id="记住、忽略和忘记过去的命令" tabindex="-1">记住、忽略和忘记过去的命令 <a class="header-anchor" href="#记住、忽略和忘记过去的命令" aria-label="Permalink to “记住、忽略和忘记过去的命令”">​</a></h3><p>命令历史记录很有用，因为它可以帮助你记住最近使用过的命令，并提醒你最近所做的更改。它还可以让你更容易地重新运行命令，特别是那些有一串参数但你不一定想重新创建的命令。定制你的历史设置可以让你对命令历史的使用变得更容易，更有效率。</p><hr>`,52)),t("p",null,[s[1]||(s[1]=a("via: ",-1)),e(i,{href:"https://www.networkworld.com/article/3537214/tweaking-history-on-linux.html"},{default:n(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3537214/tweaking-history-on-linux.html",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=a("作者：",-1)),e(i,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:n(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),e(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:n(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const C=p(r,[["render",c]]);export{x as __pageData,C as default};
